from pathlib import Path
root=Path(r'D:\en html\Sistema de Presupuestos')
component=r'''import {useEffect,useRef,useState} from 'react';
import {post} from '../services/http';
type Proposal={kind:'labor'|'material';name:string;amount:number|null;source:string};
type Draft=Proposal&{id:string;selected:boolean;amountText:string};
type Result={method:string;text:string;items:Proposal[];warnings:string[]};
export default function ImageAnalyzer({onClose,onImport}:{onClose:()=>void;onImport:(items:{kind:'labor'|'material';name:string;amount:number}[])=>void}){
 const dialog=useRef<HTMLDialogElement>(null),controller=useRef<AbortController|null>(null),alive=useRef(true);
 const [file,setFile]=useState<File|null>(null),[imageUrl,setImageUrl]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[result,setResult]=useState<Result|null>(null),[drafts,setDrafts]=useState<Draft[]>([]);
 useEffect(()=>{alive.current=true;dialog.current?.showModal();return()=>{alive.current=false;controller.current?.abort();dialog.current?.close()}},[]);
 useEffect(()=>{if(!file){setImageUrl('');return}const url=URL.createObjectURL(file);setImageUrl(url);return()=>URL.revokeObjectURL(url)},[file]);
 const pick=(next:File|undefined)=>{if(busy)return;setError('');setResult(null);setDrafts([]);setFile(null);if(!next)return;if(!['image/png','image/jpeg','image/webp'].includes(next.type)){setError('Selecciona una imagen PNG, JPG o WEBP.');return}if(next.size>10*1024*1024){setError('La imagen debe pesar como máximo 10 MB.');return}setFile(next)};
 const analyze=async()=>{if(!file||busy)return;setBusy(true);setError('');controller.current=new AbortController();const current=controller.current;try{const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('No se pudo leer el archivo.'));reader.readAsDataURL(file)});if(!alive.current)return;const response=await post<Result>('analyze-image',{image:data},current.signal);if(!alive.current)return;setResult(response);setDrafts(response.items.map(i=>({...i,id:crypto.randomUUID(),selected:true,amountText:i.amount===null?'':String(i.amount)})))}catch(e){if(alive.current&&!current.signal.aborted)setError(e instanceof TypeError?'No se pudo conectar con el analizador. Comprueba que el backend esté encendido.':e instanceof Error?e.message:'No se pudo analizar la imagen.')}finally{if(alive.current)setBusy(false)}};
 const update=(id:string,patch:Partial<Draft>)=>setDrafts(drafts.map(d=>d.id===id?{...d,...patch}:d));
 const apply=()=>{const chosen=drafts.filter(d=>d.selected);if(!chosen.length){setError('Selecciona al menos una partida para agregar.');return}if(chosen.some(d=>!d.name.trim()||!Number.isFinite(Number(d.amountText))||Number(d.amountText)<=0)){setError('Completa una descripción y un importe mayor a cero en cada partida seleccionada.');return}onImport(chosen.map(d=>({kind:d.kind,name:d.name.trim(),amount:Number(d.amountText)})))};
 return <dialog ref={dialog} className="ocr-dialog" onCancel={e=>{e.preventDefault();onClose()}}><div className="ocr-heading"><div><h2>Analizar imagen</h2><p>Lectura local de listas y boletas · revisa antes de agregar.</p></div><button className="outline" onClick={onClose}>Cerrar</button></div><div className="ocr-upload"><div className="dropzone" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();pick(e.dataTransfer.files[0])}}><label htmlFor="ocr-file">Selecciona una imagen o arrástrala aquí</label><input id="ocr-file" type="file" accept="image/png,image/jpeg,image/webp" disabled={busy} onChange={e=>pick(e.target.files?.[0])}/><small>PNG, JPG o WEBP · máximo 10 MB · texto legible</small>{file&&<span>{file.name}</span>}</div>{imageUrl&&<img className="ocr-image" src={imageUrl} alt="Imagen seleccionada para analizar"/>}</div><p className="ocr-help">La imagen se procesa en tu backend sin enviarla a una API externa. Las fotos de obras sin texto no producen cantidades ni precios.</p><button className="primary" disabled={!file||busy} onClick={analyze}>{busy?'Leyendo texto de la imagen…':'Analizar imagen seleccionada'}</button>{busy&&<p role="status" className="ocr-progress">Procesando con OCR local. El primer análisis puede tardar más.</p>}{error&&<div className="ocr-error" role="alert">{error}</div>}
 {result&&<section className="ocr-review"><h3>Revisa las partidas detectadas</h3><p>{drafts.length?`${drafts.length} propuestas. Corrige lo que haga falta; no se agregarán hasta que confirmes.`:result.text?'Se leyó texto, pero no se identificaron partidas automáticamente. Puedes agregarlas desde el texto extraído.':'No se encontró texto legible. Usa una foto más nítida de la lista o boleta.'}</p><div className="ocr-drafts">{drafts.map((d,index)=><div className="ocr-draft" key={d.id}><label className="ocr-check"><input type="checkbox" checked={d.selected} onChange={e=>update(d.id,{selected:e.target.checked})}/>Incluir {index+1}</label><label>Tipo<select value={d.kind} onChange={e=>update(d.id,{kind:e.target.value as Draft['kind']})}><option value="material">Material</option><option value="labor">Mano de obra</option></select></label><label>Descripción<input value={d.name} maxLength={300} onChange={e=>update(d.id,{name:e.target.value})}/></label><label>Importe total (S/)<input type="number" step="0.01" min="0" value={d.amountText} placeholder="Completar" onChange={e=>update(d.id,{amountText:e.target.value})}/></label><button className="icon-button danger" aria-label={'Quitar propuesta '+(index+1)} onClick={()=>setDrafts(drafts.filter(x=>x.id!==d.id))}>×</button><small className="ocr-source">Texto original: {d.source||'Partida agregada manualmente'}</small></div>)}</div><button className="outline" onClick={()=>setDrafts([...drafts,{id:crypto.randomUUID(),kind:'material',name:'',amount:null,source:'',selected:true,amountText:''}])}>+ Agregar una partida a la revisión</button><details><summary>Ver texto extraído</summary><pre>{result.text||'Sin texto reconocido'}</pre></details><div className="ocr-warning">{result.warnings.map(w=><p key={w}>{w}</p>)}</div><button className="primary full" onClick={apply} disabled={!drafts.some(d=>d.selected)}>Agregar partidas revisadas al presupuesto</button></section>}</dialog>;
}
'''
p=root/'frontend/src/features/ImageAnalyzer.tsx';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(component,encoding='utf-8')
p=root/'frontend/src/styles.css';s=p.read_text(encoding='utf-8');s+='''
.client-row{display:flex;align-items:center;gap:18px;margin:22px 4px}.client-input{flex:1}.client-input>label{display:flex;align-items:center;gap:12px;font-size:15px;font-weight:700;margin-bottom:10px}.client-summary{flex:1;border:1px solid var(--line);border-radius:12px;background:#f8fbff;padding:22px;min-width:0}.client-summary small{color:#63799d;margin-bottom:9px}.client-summary strong{font-size:14px;overflow-wrap:anywhere}.ocr-dialog{width:min(980px,94vw);max-height:92dvh;border:1px solid var(--line);border-radius:16px;padding:28px;color:#081c57;overscroll-behavior:contain}.ocr-dialog::backdrop{background:#05133370}.ocr-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:22px}.ocr-heading h2{font-size:24px;margin-bottom:7px}.ocr-upload{display:flex;gap:20px;align-items:center}.dropzone{flex:1;border:2px dashed #b9d0fa;border-radius:12px;padding:22px;background:#f7faff}.dropzone label{display:block;font-size:15px;font-weight:600;margin-bottom:16px}.dropzone input{background:white;font-size:12px}.dropzone small{font-size:11px;margin-top:12px;color:#61789c}.dropzone span{display:block;font-size:12px;margin-top:12px;overflow-wrap:anywhere}.ocr-image{width:200px;max-height:200px;object-fit:contain;border:1px solid var(--line);border-radius:8px}.ocr-help{margin:16px 0;font-size:12px}.ocr-progress{margin:14px 0;color:var(--blue)}.ocr-error{border:1px solid #ffc7ce;background:#fff3f5;color:#a92c40;border-radius:8px;padding:14px;margin:16px 0;font-size:13px}.ocr-review{margin-top:28px;border-top:1px solid var(--line);padding-top:22px}.ocr-review h3{font-size:19px}.ocr-drafts{margin:18px 0}.ocr-draft{display:grid;grid-template-columns:75px 135px 1fr 135px 24px;gap:12px;border:1px solid var(--line);padding:14px;border-radius:10px;margin-bottom:12px;align-items:end;background:#fafcff}.ocr-draft label{font-size:11px;display:block;line-height:1.6;min-width:0}.ocr-draft input,.ocr-draft select{margin-top:6px;padding:10px;font-size:12px}.ocr-draft .ocr-check{display:flex;align-items:center;align-self:center;gap:6px}.ocr-check input{width:auto}.ocr-source{grid-column:1/-1;font-size:10px;color:#6e82a1;overflow-wrap:anywhere}.ocr-review details{margin:18px 0;font-size:12px}.ocr-review summary{cursor:pointer;color:var(--blue)}.ocr-review pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f6ff;padding:14px;max-height:220px;overflow:auto}.ocr-warning{padding:12px;background:#fffaeb;border-radius:8px;margin:18px 0}.ocr-warning p{font-size:11px}button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:600px){.client-row{flex-wrap:wrap;gap:12px;margin:18px 0}.client-row>.tile-icon{display:none}.client-input,.client-summary{flex-basis:100%}.client-input>label{font-size:13px}.client-summary{padding:14px}.ocr-dialog{padding:18px}.ocr-heading{align-items:flex-start;gap:10px}.ocr-heading h2{font-size:20px}.ocr-heading p{font-size:11px}.ocr-heading button{padding:9px}.ocr-upload{flex-wrap:wrap}.dropzone{flex-basis:100%;padding:16px}.ocr-image{width:100%;max-height:150px}.ocr-draft{grid-template-columns:1fr 1fr;gap:10px}.ocr-draft label:nth-child(3){grid-column:1/-1}.ocr-draft button{grid-column:2;grid-row:4}.ocr-dialog>.primary{width:100%}}
''';p.write_text(s,encoding='utf-8')
